#include <vector>
#include <deque>
#include <algorithm>

class Solution {
public:
    int longestSubarray(std::vector<int>& nums, int limit) {
        std::deque<int> maxQ, minQ;
        int left = 0, maxLen = 0;
        for (int right = 0; right < (int)nums.size(); ++right) {
            while (!maxQ.empty() && nums[maxQ.back()] <= nums[right]) maxQ.pop_back();
            maxQ.push_back(right);
            while (!minQ.empty() && nums[minQ.back()] >= nums[right]) minQ.pop_back();
            minQ.push_back(right);
            while (nums[maxQ.front()] - nums[minQ.front()] > limit) {
                left++;
                if (maxQ.front() < left) maxQ.pop_front();
                if (minQ.front() < left) minQ.pop_front();
            }
            maxLen = std::max(maxLen, right - left + 1);
        }
        return maxLen;
    }
};

import java.util.*;

class Solution {
    public int longestSubarray(int[] nums, int limit) {
        Deque<Integer> maxQ = new ArrayDeque<>();
        Deque<Integer> minQ = new ArrayDeque<>();
        int left = 0, maxLen = 0;
        for (int right = 0; right < nums.length; right++) {
            while (!maxQ.isEmpty() && nums[maxQ.peekLast()] <= nums[right]) maxQ.pollLast();
            maxQ.offerLast(right);
            while (!minQ.isEmpty() && nums[minQ.peekLast()] >= nums[right]) minQ.pollLast();
            minQ.offerLast(right);
            while (nums[maxQ.peekFirst()] - nums[minQ.peekFirst()] > limit) {
                left++;
                if (maxQ.peekFirst() < left) maxQ.pollFirst();
                if (minQ.peekFirst() < left) minQ.pollFirst();
            }
            maxLen = Math.max(maxLen, right - left + 1);
        }
        return maxLen;
    }
}

var longestSubarray = function(nums, limit) {
    const maxQ = [];
    const minQ = [];
    let maxHead = 0, minHead = 0;
    let left = 0, maxLen = 0;
    for (let right = 0; right < nums.length; right++) {
        while (maxQ.length > maxHead && nums[maxQ[maxQ.length - 1]] <= nums[right]) maxQ.pop();
        maxQ.push(right);
        while (minQ.length > minHead && nums[minQ[minQ.length - 1]] >= nums[right]) minQ.pop();
        minQ.push(right);
        while (nums[maxQ[maxHead]] - nums[minQ[minHead]] > limit) {
            left++;
            if (maxQ[maxHead] < left) maxHead++;
            if (minQ[minHead] < left) minHead++;
        }
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
};
